import yaml,glob
# roadmap
items={}
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    d=yaml.safe_load(open(f)); items[d['id']]=d
active=[i for i,d in items.items() if d.get('status')=='active']
print('ACTIVE ROADMAP:', len(active), '(cap 8) ->', 'OK' if len(active)<=8 else 'WARN')
kids={}
for i,d in items.items():
    p=(d.get('metadata') or {}).get('parent')
    if p: kids.setdefault(p,[]).append(i)
for p,cs in kids.items():
    ps=items[p].get('status')
    css=[items[c].get('status') for c in cs]
    if ps!='done' and all(s in ('done','rejected') for s in css):
        print('WARN all-children-done:', p, ps)
    if ps=='done' and any(s not in ('done','rejected') for s in css):
        print('WARN parent-done-child-open:', p, [c for c in cs if items[c].get('status') not in ('done','rejected')])
"
